-- Acting-candidate approval notices are generated by the portal, even though
-- the approving ACM remains the audit actor stored on the post. Remove the
-- personal signature from notices generated before the portal-author fix.
update public.chat_posts
set body = regexp_replace(
  body,
  E'Warm regards,\\n[^\\n]+\\s*$',
  E'Warm regards,\\nThe Portal'
)
where subject in (
  'Acting candidates confirmed',
  'Acting candidate changes approved'
)
  and body like '%The full adjudication panel%'
  and body ~ E'Warm regards,\\n[^\\n]+\\s*$';
